import json, re

def last_number(text):
    nums = re.findall(r"(\-?[0-9\.\,]+)", text)
    vals = []
    for n in reversed(nums):
        if n not in ("", "."):
            vals.append(n.replace(",", ""))
            break
    return vals[0] if vals else None

def grade(path, limit=None):
    n, correct, noparse = 0, 0, 0
    empty = 0
    lens = []
    with open(path) as f:
        for line in f:
            d = json.loads(line)
            # find fields
            resp = d.get('response') or d.get('generation') or d.get('output') or ''
            gt = d.get('ground_truth') or d.get('gold') or d.get('answer') or ''
            n += 1
            if n == 1:
                print("FIELDS:", sorted(d.keys()))
                print("SAMPLE resp[:400]:", repr(resp[:400]))
                print("SAMPLE gt:", repr(gt))
            if not resp.strip():
                empty += 1
            lens.append(len(resp))
            pred = last_number(resp)
            if pred is None:
                noparse += 1
                continue
            try:
                if abs(float(pred) - float(str(gt).replace(',',''))) < 1e-6:
                    correct += 1
            except ValueError:
                pass
            if limit and n >= limit:
                break
    print(f"{path}: n={n} acc={correct/n:.4f} noparse={noparse} empty={empty} avg_len={sum(lens)/len(lens):.0f}")

for step in (0, 25, 50):
    grade(f'/workspace/results/grpo_gsm8k/val_generations/{step}.jsonl')
EOF

